steps.script:
var nb = ChargeMove11e.path_blocking_models("U_NOBZ_A", GameState.state)
var bb = ChargeMove11e.path_blocking_models("U_BOYZ_C", GameState.state)
return nb.all(func(b): return b.unit_id == "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H") and bb.any(func(b): return b.unit_id == "U_WITCHSEEKERS_D")

var cc = tree.current_scene.charge_controller
for i in range(cc.unit_selector.get_item_count()):
	if str(cc.unit_selector.get_item_metadata(i)) == "U_NOBZ_A":
		return i
return -1

var cc = tree.current_scene.charge_controller
for i in range(cc.target_list.get_item_count()):
	if str(cc.target_list.get_item_metadata(i)) == "U_CUSTODIAN_GUARD_B":
		return i
return -1

for s in range(1, 3000):
	RulesEngine.set_test_seed(s)
	var r = RulesEngine.RNGService.new(-1).roll_d6(2)
	if int(r[0]) + int(r[1]) >= 10:
		RulesEngine.set_test_seed(s)
		print("[wp-g3] charge seed ", s, " -> ", r)
		return s
return -1

var b = tree.root.find_children("KeepRollButton", "", true, false)
if b.size() > 0 and b[0].is_visible_in_tree():
	b[0].emit_signal("pressed")
return true

var pc = PhaseManager.get_current_phase_instance().pending_charges.get("U_NOBZ_A", {})
print("[wp-g3] charge roll ", pc.get("distance", -1))
return int(pc.get("distance", -1))

var cc = tree.current_scene.charge_controller
var ws = ChargeMove11e.path_blocking_models("U_BOYZ_C", GameState.state).filter(func(b): return b.unit_id == "U_WITCHSEEKERS_C")
var n := 0
for k in cc._model_charge_paths:
	var m = cc._get_charge_group_model(k)
	var orig = cc._model_origin_positions.get(k, null)
	var path = cc._model_charge_paths[k]
	if ChargeMove11e.path_crosses_models(m, path, ws) != "":
		n += 1
print("[wp-g3] snapped lanes through the Witchseekers: ", n, " of ", cc._model_charge_paths.size())
return n > 0

var ys = 0.0
for m in GameState.get_unit("U_WITCHSEEKERS_C").models:
	ys = max(ys, float(m.position.y))
var ok := false
for m in GameState.get_unit("U_NOBZ_A").models:
	if float(m.position.y) > ys:
		ok = true
return ok

var ph = PhaseManager.get_current_phase_instance()
var b = GameState.get_unit("U_BOYZ_C").models[2]
var bp = Vector2(b.position.x, b.position.y)
var d = GameState.get_unit("U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H").models[0]
var dp = Vector2(d.position.x, d.position.y)
var r1 = ph._g3_validate_paths_through_models("U_BOYZ_C", {"m3": [[bp.x, bp.y], [bp.x, bp.y + 276.0]]})
var r2 = ph._g3_validate_paths_through_models("U_NOBZ_A", {"m3": [[dp.x, dp.y - 120.0], [dp.x, dp.y + 120.0]]})
print("[wp-g3] boyz lane: ", r1, " nobz through vehicle: ", r2)
return not r1.valid and not r2.valid
